#---------------------------#
# DEBUG AREA 1
#---------------------------#
@token       = debug-area-1
@name        = DEBUG Area 1
@level       = 1
@size        = 25 x 34
@sheet       = mmrpg-overworld-2k25
#---------------------------#
@portals[]   = spawn(11-16)
#---------------------------#
@portals[]   = subspace-portal(19-28, debug-area-0__surface-portal)
#---------------------------#
@portals[]   = north-portal-1(11-14, debug-area-1__north-portal-2)
@portals[]   = north-portal-2(11-5, debug-area-1__north-portal-1)
@portals[]   = north-exit(11-1, debug-area-1n__south-exit, up-only)
#---------------------------#
@portals[]   = east-portal-1(13-16, debug-area-1__east-portal-2)
@portals[]   = east-portal-2(21-16, debug-area-1__east-portal-1)
@portals[]   = east-exit(25-16, debug-area-1e__west-exit, right-only)
#---------------------------#
@portals[]   = west-portal-1(9-16, debug-area-1__west-portal-2)
@portals[]   = west-portal-2(5-16, debug-area-1__west-portal-1)
@portals[]   = west-exit(1-16, debug-area-1w__east-exit, left-only)
#---------------------------#
@portals[]   = south-portal-1(11-18, debug-area-1__south-portal-2)
@portals[]   = south-portal-2(11-30, debug-area-1__south-portal-1)
@portals[]   = south-exit(11-34, debug-area-1s__north-exit, down-only)
#---------------------------#
# FIELD AND TERRAIN
#--------------------
@field       = gentle-countryside
@terrain[]   = grass(gentle-countryside)
@terrain[]   = subspace(prototype-subspace)
#---------------------------#
# FIELD MUSIC CONFIG
#--------------------
@music[]     = default(opening-1-mm9)
@music[]     = dangerzone(opening-stage-rnf)
@music[]     = mecha-battle(opening-stage-mm7)
@music[]     = boss-battle(wily-fortress-1-mm7)
#---------------------------#
# ENCOUNTERS AND HABITATS
#--------------------------
@encounters  = met(2),trille-bot(1)
@habitats[]  = met(grass)
@habitats[]  = trille-bot(subspace)
#---------------------------#
# SPAWN AREA BUFFER
# + EVENT PANELS
# + GIFT ITEMS
#----------------------
@groups[]    = no-encounters_spawn-buffer(9-14...13-18)
@events[]    = auto-heal(9-14, healpad, any, trigger-effects, restore-team-energy, restore-team-weapons)
@events[]    = auto-reset(13-14, resetpad, any, trigger-effects, reset-team-attack, reset-team-defense, reset-team-speed)
@items[]     = first-consumable-eti(8-19, energy-tank, x1, always)
@items[]     = first-consumable-wti(14-19, weapon-tank, x1, always)
#---------------------------#
# LIGHT PLAYER PLATFORM
# + INIT ITEMS
#------------------------
@events[]     = light-platform-left(10-8, lightpad-left, any, drop-zone, item:light-program, activate-player-platform)
@events[]     = light-platform-middle(11-8, lightpad-middle, any, drop-zone, item:light-heart, activate-player-platform)
@events[]     = light-platform-right(12-8, lightpad-right, any, drop-zone, item:copy-core, activate-player-platform)
@items[]      = light-init-program(19-26, light-program, anchored)
@items[]      = light-init-heart(17-16, light-heart__1, anchored)
@items[]      = light-init-core(3-24, copy-core, anchored)
#---------------------------#
# INTRO ENCOUNTER
#------------------
@mechas[]    = light-runway-mecha(11-12, met, 1)
#---------------------------#
# MECHA PORTAL BOSSES
#----------------------
@mechas[]    = south-exit-mecha(11-34, octone, 1)
@mechas[]    = north-exit-mecha(11-1, frosty-throwman, 2)
@mechas[]    = west-exit-mecha(1-16, rockscotch, 3)
@mechas[]    = east-exit-mecha(25-16, antlin-g, 4)
#---------------------------#
# ITEMS CODES PICKUP
#---------------------
@items[]     = item-codes-pickup(14-22, item-codes)
#---------------------------#
# ITEM CORRIDOR PICKUPS
# + STARTER ABILITIES
#------------------------
@items[]      = energy-pellet-pickup(15-10, energy-pellet)
@items[]      = energy-capsule-pickup(15-8, energy-capsule)
@items[]      = weapon-pellet-pickup(16-10, weapon-pellet)
@items[]      = weapon-capsule-pickup(16-8, weapon-capsule)
@items[]      = attack-pellet-pickup(17-10, attack-pellet)
@items[]      = attack-capsule-pickup(17-8, attack-capsule)
@items[]      = defense-pellet-pickup(18-10, defense-pellet)
@items[]      = defense-capsule-pickup(18-8, defense-capsule)
@items[]      = speed-pellet-pickup(19-10, speed-pellet)
@items[]      = speed-capsule-pickup(19-8, speed-capsule)
#------------------------
@abilities[]  = light-buster-pickup(7-8, light-buster)
@abilities[]  = wily-buster-pickup(6-8, wily-buster)
@abilities[]  = cossack-buster-pickup(5-8, cossack-buster)
@abilities[]  = copy-shot-pickup(7-10, copy-shot)
@abilities[]  = copy-soul-pickup(6-10, copy-soul)
@abilities[]  = copy-style-pickup(5-10, copy-style)
#---------------------------#
# ISLAND BUTTON 1 + EVENTS
#-------------------------
@buttons[]   = island-button-1(17-14, green, up, set-group-terrain, island-paths-1, grass)
@groups[]    = island-paths-1(17-19...17-22, 16-22)
@mechas[]    = island-button-1-guard-1(16-14, met, 1)
@mechas[]    = island-button-1-guard-2(18-14, met, 1)
#---------------------------#
# ISLAND BUTTON 2 + EVENTS
#-------------------------
@buttons[]   = island-button-2(14-21, green, up, set-group-terrain, island-paths-2, grass)
@groups[]    = island-paths-2(10-22...12-22)
@mechas[]    = island-button-2-guard-1(13-21, met, 2)
@mechas[]    = island-button-2-guard-2(15-21, met, 2)
#---------------------------#
# ROLL RESCUE MISSION + EVENTS
#----------------------
@rescues[]   = rescue-roll-robot(7-23, roll, 2)
@mechas[]    = rescue-roll-guard-1(7-22, sniper-joe, 2)
@mechas[]    = rescue-roll-guard-2(8-23, sniper-joe, 2)
@items[]     = rescue-roll-pickup-1(9-21, extra-life)
#---------------------------#
# SUBSPACE BUTTON + EVENTS
#---------------------------
@bosses[]    = subspace-portal-boss(19-28, trill, 10, speed)
@items[]     = subspace-light-heart(19-29, light-heart__2)
@buttons[]   = subspace-button(19-30, purple, up, set-group-terrain, subspace-path, subspace)
@groups[]    = subspace-path(14-24...14-28, 15-28)
#---------------------------#
# NO ENCOUNTERS
#---------------------------
@groups[]    = no-encounters_temp(1-1...25-34)
#---------------------------#
# OVERWORLD (BLOCKS & HAZARDS)
# blocks are like buttons (can't pass through, but something happens nearby)
# like: @blocks[] = foobar-tree(pos, sprite, alt, destructable, weaknesses)
# hazards are like events (can pass over, and something happens when you do)
# like: @hazard[] = foobar-panel(pos, sprite, alt, filter, trigger-effects, restore-team-energy, restore-team-weapons)
#---------------------------
@blocks[]    = exit-block-north(11-4, super-block, arctic-jungle)
@blocks[]    = exit-block-east(22-16, super-block, oil-wells)
@blocks[]    = exit-block-south(11-31, super-block, waterfall-institute)
@blocks[]    = exit-block-west(4-16, super-block, maniacal-hideaway)
#---------------------------
@blocks[]    = fence-block-1(16-17, fence-block)
@blocks[]    = fence-block-2(17-17, fence-block)
@blocks[]    = fence-block-3(18-17, fence-block)
#---------------------------
@blocks[]    = super-block-1(8-18, super-block, mountain-mines)
@blocks[]    = super-block-2(9-18, super-block, mountain-mines)
@blocks[]    = super-block-3(9-19, super-block, mountain-mines)
#---------------------------
@blocks[]    = super-block-4(14-18, super-block, mountain-mines)
@blocks[]    = super-block-5(13-18, super-block, mountain-mines)
@blocks[]    = super-block-6(13-19, super-block, mountain-mines)
#---------------------------
@hazards[]    = frozen-hazard-1(10-3, frozen-foothold)
@hazards[]    = frozen-hazard-2(11-3, frozen-foothold)
@hazards[]    = frozen-hazard-3(12-3, frozen-foothold)
#---------------------------
@hazards[]    = flame-hazard-1(3-15, flame-pillar)
@hazards[]    = flame-hazard-2(3-16, flame-pillar)
@hazards[]    = flame-hazard-3(3-17, flame-pillar)
#---------------------------
@hazards[]    = bubble-hazard-1(10-32, foamy-bubbles)
@hazards[]    = bubble-hazard-2(11-32, foamy-bubbles)
@hazards[]    = bubble-hazard-3(12-32, foamy-bubbles)
#---------------------------
@hazards[]    = oil-hazard-1(23-15, crude-oil)
@hazards[]    = oil-hazard-2(23-16, crude-oil)
@hazards[]    = oil-hazard-3(23-17, crude-oil)
#---------------------------#
#@hazards[]    = test-hazard-1(11-17, woolly-clouds)
